"use client";

import * as React from "react";
import { GripHorizontalIcon } from "lucide-react";
import { Popover as PopoverPrimitive, Slot } from "radix-ui";

import { useV4CollisionBoundary, useV4PortalContainer } from "../scope";

import { FrameScope } from "../lib/frame-context";
import { useOwnedEscape } from "../lib/use-owned-escape";
import { cn } from "../lib/utils";
import { Icon } from "./icon";

import controls from "./controls.module.css";
import menu from "./menu.module.css";
import styles from "./popover.module.css";

const PopoverOpenContext = React.createContext(false);

function Popover({
  open,
  defaultOpen = false,
  onOpenChange,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen);
  const current = open ?? uncontrolled;
  return (
    <PopoverOpenContext value={current}>
      <PopoverPrimitive.Root
        data-slot="popover"
        open={current}
        onOpenChange={(next) => {
          if (open === undefined) setUncontrolled(next);
          onOpenChange?.(next);
        }}
        {...props}
      />
    </PopoverOpenContext>
  );
}

function PopoverTrigger({ ref, ...props }: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger ref={ref} data-slot="popover-trigger" {...props} />;
}
PopoverTrigger.displayName = "PopoverTrigger";

type DragOffset = { x: number; y: number };

const restingOffset: DragOffset = { x: 0, y: 0 };

const tabbable =
  'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

const dragKeys: Record<string, DragOffset | undefined> = {
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 }
};

function clampDragOffset(
  content: HTMLElement,
  current: DragOffset,
  next: DragOffset,
  padding: React.ComponentProps<typeof PopoverPrimitive.Content>["collisionPadding"],
  boundary: HTMLElement | undefined
): DragOffset {
  const inset =
    typeof padding === "number"
      ? { top: padding, right: padding, bottom: padding, left: padding }
      : { top: 0, right: 0, bottom: 0, left: 0, ...padding };
  const frame = boundary?.getBoundingClientRect();
  const viewport = document.documentElement;
  const minLeft = Math.max(frame?.left ?? 0, 0) + inset.left;
  const minTop = Math.max(frame?.top ?? 0, 0) + inset.top;
  const maxRight = Math.min(frame?.right ?? Infinity, viewport.clientWidth) - inset.right;
  const maxBottom = Math.min(frame?.bottom ?? Infinity, viewport.clientHeight) - inset.bottom;
  const rect = content.getBoundingClientRect();
  const left = rect.left - current.x;
  const top = rect.top - current.y;
  return {
    x: Math.max(minLeft - left, Math.min(next.x, maxRight - left - rect.width)),
    y: Math.max(minTop - top, Math.min(next.y, maxBottom - top - rect.height))
  };
}

function PopoverContent({
  className,
  collisionPadding = 8,
  align = "center",
  sideOffset = 4,
  surface = "card",
  draggable = false,
  onEscapeKeyDown,
  onOpenAutoFocus,
  style,
  children,
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content>, "draggable"> & {
  surface?: "card" | "menu";
  draggable?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof PopoverPrimitive.Content>> }) {
  const escape = useOwnedEscape(ref, onEscapeKeyDown);
  const boundary = useV4CollisionBoundary();
  const open = React.useContext(PopoverOpenContext);
  const [offset, setOffset] = React.useState(restingOffset);
  const [openedFor, setOpenedFor] = React.useState(open);
  if (open !== openedFor) {
    setOpenedFor(open);
    if (open) setOffset(restingOffset);
  }
  const content = React.useRef<HTMLElement | null>(null);
  const pointer = React.useRef<{ x: number; y: number; offset: DragOffset } | undefined>(undefined);
  const instructions = React.useId();
  const dragged = offset.x !== 0 || offset.y !== 0;

  const moveTo = (next: DragOffset) => {
    if (!content.current) return;
    setOffset(clampDragOffset(content.current, offset, next, collisionPadding, boundary));
  };
  const grab = (handle: HTMLElement) => {
    content.current = handle.closest<HTMLElement>('[data-slot="popover-content"]');
  };

  React.useEffect(() => {
    if (!dragged) return undefined;
    let frame = 0;
    const reclamp = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const node = content.current;
        if (node)
          setOffset((current) =>
            clampDragOffset(node, current, current, collisionPadding, boundary)
          );
      });
    };
    window.addEventListener("resize", reclamp);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", reclamp);
    };
  }, [dragged, collisionPadding, boundary]);

  return (
    <PopoverPrimitive.Portal container={useV4PortalContainer()}>
      <PopoverPrimitive.Content
        ref={escape.ref}
        data-slot="popover-content"
        collisionPadding={collisionPadding}
        collisionBoundary={boundary}
        align={align}
        sideOffset={sideOffset}
        data-surface={surface}
        data-scroll-fade="y"
        className={cn(
          "z-50",
          menu.surface,
          surface === "menu" ? menu.panel : menu.card,
          menu.motion,
          className
        )}
        style={dragged ? { ...style, transform: `translate(${offset.x}px, ${offset.y}px)` } : style}
        {...props}
        onEscapeKeyDown={escape.onEscapeKeyDown}
        onOpenAutoFocus={(event) => {
          onOpenAutoFocus?.(event);
          if (!draggable || event.defaultPrevented) return;
          event.preventDefault();
          const panel = event.currentTarget as HTMLElement;
          const field = Array.from(panel.querySelectorAll<HTMLElement>(tabbable)).find(
            (element) =>
              element.dataset.slot !== "popover-drag-handle" && !element.closest("[hidden]")
          );
          (field ?? panel).focus();
        }}
      >
        {draggable && (
          <button
            type="button"
            data-slot="popover-drag-handle"
            aria-label="Move"
            aria-describedby={instructions}
            className={cn(styles.dragHandle, controls.focusOutline)}
            onPointerDown={(event) => {
              if (event.button !== 0) return;
              grab(event.currentTarget);
              event.currentTarget.setPointerCapture(event.pointerId);
              pointer.current = { x: event.clientX, y: event.clientY, offset };
            }}
            onPointerMove={(event) => {
              const start = pointer.current;
              if (!start) return;
              moveTo({
                x: start.offset.x + event.clientX - start.x,
                y: start.offset.y + event.clientY - start.y
              });
            }}
            onPointerUp={() => {
              pointer.current = undefined;
            }}
            onLostPointerCapture={() => {
              pointer.current = undefined;
            }}
            onKeyDown={(event) => {
              const direction = dragKeys[event.key];
              if (!direction) return;
              event.preventDefault();
              grab(event.currentTarget);
              const step = parseFloat(
                getComputedStyle(event.currentTarget).getPropertyValue(
                  event.shiftKey ? "--v4-space-48" : "--v4-space-8"
                )
              );
              moveTo({ x: offset.x + direction.x * step, y: offset.y + direction.y * step });
            }}
          >
            <Icon icon={GripHorizontalIcon} />
            <span id={instructions} hidden>
              Use the arrow keys to move the popover. Hold Shift to move it further.
            </span>
          </button>
        )}
        <FrameScope framed={false}>{children}</FrameScope>
      </PopoverPrimitive.Content>
    </PopoverPrimitive.Portal>
  );
}
PopoverContent.displayName = "PopoverContent";

function PopoverAnchor({
  asChild,
  virtualRef,
  ref,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  const node = React.useRef<HTMLDivElement | null>(null);
  const attach = React.useCallback(
    (element: HTMLDivElement | null) => {
      node.current = element;
      if (typeof ref === "function") ref(element);
      else if (ref) {
        ref.current = element;
      }
    },
    [ref]
  );
  // The trigger can re-claim the anchor on a later commit (StrictMode ref replays, re-mounts in a
  // Dialog) and a virtual anchor only re-announces when its element changes, so it remounts on
  // every open to point the popper back at this anchor.
  const generation = React.useContext(PopoverOpenContext) ? "open" : "closed";
  if (virtualRef)
    return (
      <PopoverPrimitive.Anchor
        key={generation}
        ref={ref}
        data-slot="popover-anchor"
        virtualRef={virtualRef}
        hidden
        {...props}
      />
    );
  // Radix registers a real anchor only when its node attaches, and its trigger re-mounts without
  // the anchor wrapper once a custom anchor exists, so the popper measures through a virtual ref.
  const Comp = asChild ? Slot.Root : "div";
  return (
    <>
      <Comp ref={attach} data-slot="popover-anchor" {...props} />
      <PopoverPrimitive.Anchor key={generation} virtualRef={node} hidden />
    </>
  );
}
PopoverAnchor.displayName = "PopoverAnchor";

function PopoverHeader({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="popover-header"
      className={cn("flex flex-col gap-0.5", className)}
      {...props}
    />
  );
}
PopoverHeader.displayName = "PopoverHeader";

function PopoverTitle({
  className,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"h2"> & { ref?: React.Ref<HTMLHeadingElement> }) {
  return (
    <h2 ref={ref} data-slot="popover-title" className={cn("", className)} {...props}>
      {children}
    </h2>
  );
}
PopoverTitle.displayName = "PopoverTitle";

function PopoverDescription({ className, ref, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      ref={ref}
      data-slot="popover-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  );
}
PopoverDescription.displayName = "PopoverDescription";

export {
  Popover,
  PopoverAnchor,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger
};

.field {
  --v4-field-height: var(--v4-size-control-sm);
  --v4-field-inline: var(--v4-space-control-inline-sm);
  --v4-field-nested: var(--v4-size-nested-sm);
  box-sizing: border-box;
  min-height: var(--v4-field-height);
  padding-block: calc(
    (var(--v4-field-height) - var(--v4-type-body-line-height)) / 2 - var(--v4-size-control-border)
  );
  padding-inline: var(--v4-field-inline);
  border: var(--v4-size-control-border) solid var(--v4-control);
  border-radius: 0;
  background-color: var(--v4-control-surface);
  color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.field[data-size="xs"] {
  --v4-field-height: var(--v4-size-control-xs);
  --v4-field-inline: var(--v4-space-6);
  --v4-field-nested: calc(
    var(--v4-size-control-xs) - 2 *
      (var(--v4-space-control-slot-inset) + var(--v4-size-control-border))
  );
  padding-block: calc(
    (var(--v4-field-height) - var(--v4-type-caption-line-height)) / 2 -
      var(--v4-size-control-border)
  );
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
}
.field[data-size="xs"]:is(.fieldBox, .inputGroup) {
  padding-block: 0;
}
.field[data-size="xs"] .leading > svg {
  width: var(--v4-size-icon-xs);
  height: var(--v4-size-icon-xs);
}
.field[data-size="md"] {
  --v4-field-height: var(--v4-size-control-md);
  --v4-field-inline: var(--v4-space-control-inline-md);
  --v4-field-nested: var(--v4-size-nested-md);
}
.field[data-size="lg"] {
  --v4-field-height: var(--v4-size-control-lg);
  --v4-field-inline: var(--v4-space-control-inline);
  --v4-field-nested: var(--v4-size-nested-lg);
}
.field::placeholder,
.field ::placeholder {
  color: var(--v4-muted);
}
@media (hover: hover) {
  .field:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-control-surface-hover);
  }
}
.field:is(:focus-visible, [aria-expanded="true"]),
.field[data-field-box][data-control-focus] {
  border-color: var(--v4-ink);
  box-shadow: 0 0 0 var(--v4-size-focus-glow) var(--v4-focus-ring);
}
.field:is([aria-invalid="true"], [data-invalid]),
.field[data-field-box][data-control-invalid] {
  border-color: var(--v4-control-invalid-border);
}
.field:is([aria-invalid="true"], [data-invalid]):is(:focus-visible, [aria-expanded="true"]),
.field:is([aria-invalid="true"], [data-invalid])[data-field-box][data-control-input-focus],
.field[data-field-box][data-control-invalid][data-control-invalid-focus] {
  border-color: var(--v4-bad);
  box-shadow: 0 0 0 var(--v4-size-focus-glow) var(--v4-focus-ring-bad);
}
.field:is(:disabled, [aria-disabled="true"]),
.field[data-field-box][data-control-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.field:is([readonly], [data-field-box][data-control-readonly]) {
  background-color: var(--v4-paper);
}
.fieldBox {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-control-gap);
  padding-block: 0;
  cursor: text;
}
.fieldBox[data-trailing] {
  --v4-kbd-host-block: calc(var(--v4-field-height) - 2 * var(--v4-size-control-border));
  --v4-kbd-host-end: var(--v4-space-control-slot-inset);
  padding-inline-end: var(--v4-space-control-slot-inset);
}
.bare {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  min-height: calc(var(--v4-field-height) - 2 * var(--v4-size-control-border));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}
.bare:disabled {
  cursor: not-allowed;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.leading,
.chevron {
  display: inline-flex;
  flex: none;
  color: var(--v4-muted);
  pointer-events: none;
}
.chevron {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.trigger {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-control-gap);
  text-align: start;
  white-space: nowrap;
}
@media (hover: hover) {
  .triggerHover:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-action-outline-hover);
  }
}
.triggerHover[aria-expanded="true"] {
  background-color: var(--v4-action-outline-hover);
}
.trigger > :first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger [data-placeholder],
.trigger[data-placeholder] > :first-child {
  color: var(--v4-muted);
}
.textarea {
  min-height: calc(2 * var(--v4-space-32));
  field-sizing: content;
  resize: vertical;
}
/* field-sizing: content ignores the rows attribute, so rows becomes the starting height: that many lines plus the field's padding and border, and content still grows it. */
.textarea[data-rows] {
  min-height: calc(
    var(--v4-textarea-rows) * 1lh + var(--v4-field-height) - var(--v4-type-body-line-height)
  );
}
.textarea[data-mono] {
  font-family: var(--v4-type-mono-font-family);
  font-size: var(--v4-type-mono-font-size);
  line-height: var(--v4-type-mono-line-height);
  font-weight: var(--v4-type-mono-font-weight);
  letter-spacing: var(--v4-type-mono-letter-spacing);
  tab-size: 2;
}
.searchRow {
  display: flex;
  min-height: var(--v4-size-control-lg);
  align-items: center;
  gap: var(--v4-space-8);
  padding-inline: calc(var(--v4-space-menu-inset) + var(--v4-space-8));
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  cursor: text;
}
.searchRow:focus-within {
  color: var(--v4-ink);
}
.searchRow > svg {
  flex: none;
  pointer-events: none;
}
.searchRow > input {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--v4-ink);
  caret-color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
}
.searchRow > input::placeholder {
  color: var(--v4-muted);
}
.searchTrailing {
  display: inline-flex;
  flex: none;
  align-items: center;
  color: var(--v4-muted);
}
.searchRow > input:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.focusOutline:focus-visible,
.focusOutlineWithin[data-child-focus-visible] {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: var(--v4-size-focus-ring);
}
.focusOutlineInset:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.selectTrigger {
  width: 100%;
  min-width: 0;
}
.selectTrigger [data-slot="select-value"] {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.group[data-variant="toolbar"] {
  gap: var(--v4-space-4);
}
.group[data-variant="spaced"] {
  gap: var(--v4-space-8);
  flex-wrap: wrap;
}
.group[data-variant="toolbar"] > *,
.group[data-variant="spaced"] > * {
  border-radius: 0;
}
.group[data-variant="toolbar"] > [data-slot="button"],
.group[data-variant="spaced"] > [data-slot="button"] {
  border-width: 1px;
}
:where(.card) {
  --v4-card-inset: var(--v4-space-surface-inset);
  --v4-card-body-inset: var(--v4-card-inset);
  --v4-card-lead: 0px;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  padding: 0;
  background: var(--v4-pop);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  border-radius: 0;
  box-shadow: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  container-type: inline-size;
}
.card[data-size="sm"] {
  --v4-card-inset: var(--v4-space-surface-inset-sm);
}
:where(.cardHeader) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--v4-space-4) var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-card-inset);
}
:where(.cardHeading) {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
:where(.cardBody) {
  min-width: 0;
  padding: var(--v4-card-body-inset);
  padding-inline-start: calc(var(--v4-card-body-inset) + var(--v4-card-lead));
}
.cardHeader + .cardBody {
  padding-top: 0;
}
.cardPlain {
  background: var(--v4-surface);
}
.cardPlain:not([data-has-slots]) {
  padding: var(--v4-card-body-inset);
}
.cardInset {
  display: flex;
  flex-direction: column;
}
.card > .cardBody,
.card > .cardInset,
.cardInset > .cardBody {
  flex-grow: 1;
}
.card[data-variant="framed"] > .cardHeader {
  align-items: center;
}
.card[data-variant="framed"] > .cardHeader .cardTitleGroup {
  flex: 1 1 var(--v4-size-cell-min);
  align-items: center;
}
.card[data-variant="framed"] > .cardHeader > [data-slot="card-description"] {
  flex-basis: 100%;
  order: 1;
}
.card[data-variant="framed"] > .cardHeader + .cardBody {
  padding-top: var(--v4-card-body-inset);
}
.card[data-variant="framed"] > .cardBody[data-before-footer] {
  border-bottom: 0;
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  box-shadow: none;
}
.card[data-variant="framed"] > .cardBody + .cardFooter:not([data-placement="frame"]) {
  border-top-color: var(--v4-line-soft);
  border-start-start-radius: 0;
  border-start-end-radius: 0;
}
.card[data-variant="framed"][data-flush] > .cardHeader {
  border-bottom: 0;
}
.card[data-variant="framed"][data-flush] > .cardBody {
  padding: 0;
  overflow: hidden;
}
.cardTitleGroup {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  min-width: 0;
  grid-column: 1;
  grid-row: 1 / span 2;
}
.cardCopy {
  flex: 1;
  min-width: 0;
}
.cardHeader > [data-slot="card-title"],
.cardHeader > [data-slot="card-description"] {
  grid-column: 1;
}
.cardDescription {
  color: var(--v4-text2);
  margin-top: var(--v4-space-4);
  overflow-wrap: anywhere;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
